    skCircle(p1, "circle1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(p1);
    loft(context, id + "loft1", { "sheetProfilesArray" : [{ "sheetProfileEntities" : qSketchRegion(id + "p0") }, { "sheetProfileEntities" : qSketchRegion(id + "p1") }], "bodyType" : ExtendedToolBodyType.SOLID, "operationType" : NewBodyOperationType.NEW, "startCondition" : LoftEndDerivativeType.DEFAULT, "endCondition" : LoftEndDerivativeType.DEFAULT, "matchConnections" : true, "connections" : [{ "connectionEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(15, 0, 0) * millimeter), qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.EDGE)]), "connectionEdgeQueries" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(15, 0, 0) * millimeter), qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.EDGE)]), "connectionEdgeParameters" : [0.5, 0] }, { "connectionEntities" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(0, 5, 0) * millimeter), qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.EDGE)]), "connectionEdgeQueries" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "p0", EntityType.BODY), BodyType.SHEET), EntityType.EDGE), vector(0, 5, 0) * millimeter), qOwnedByBody(qBodyType(qCreatedBy(id + "p1", EntityType.BODY), BodyType.SHEET), EntityType.EDGE)]), "connectionEdgeParameters" : [0.5, 0.333333] }] });
    return { "faces" : faceProbe(context, qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID)), "volume" : roundToPrecision(evVolume(context, { "entities" : qBodyType(qCreatedBy(id + "loft1", EntityType.BODY), BodyType.SOLID) }) / millimeter ^ 3, 6) };
}
